  1→import { useEffect, useRef, useState } from "react";
  2→import { ApiError, bulkIssue, fetchCourses, messageOf } from "../api";
  3→import type { BulkResponse, Course } from "../types";
  4→import { Banner } from "./Banner";
  5→
  6→type CoursesState =
  7→  | { kind: "loading" }
  8→  | { kind: "ready"; courses: Course[] }
  9→  | { kind: "error"; message: string };
 10→
 11→type ResultState =
 12→  | { kind: "idle" }
 13→  | { kind: "pending" }
 14→  | { kind: "done"; data: BulkResponse; replayed: boolean }
 15→  | { kind: "error"; message: string; retryable: boolean };
 16→
 17→interface BulkIssueDialogProps {
 18→  actor: string;
 19→  onClose: () => void;
 20→  onCompleted: (message: string) => void;
 21→}
 22→
 23→export function BulkIssueDialog({ actor, onClose, onCompleted }: BulkIssueDialogProps) {
 24→  const [courses, setCourses] = useState<CoursesState>({ kind: "loading" });
 25→  const [courseId, setCourseId] = useState("");
 26→  const [result, setResult] = useState<ResultState>({ kind: "idle" });
 27→  const [reload, setReload] = useState(0);
 28→  const keyRef = useRef<string>(crypto.randomUUID());
 29→  const closeRef = useRef<HTMLButtonElement>(null);
 30→
 31→  useEffect(() => {
 32→    const controller = new AbortController();
 33→    setCourses({ kind: "loading" });
 34→    fetchCourses(actor, controller.signal)
 35→      .then((data) => setCourses({ kind: "ready", courses: data.courses }))
 36→      .catch((error: unknown) => {
 37→        if (error instanceof DOMException && error.name === "AbortError") return;
 38→        setCourses({ kind: "error", message: messageOf(error) });
 39→      });
 40→    return () => controller.abort();
 41→  }, [actor, reload]);
 42→
 43→  useEffect(() => {
 44→    if (courses.kind !== "ready" || courseId) return;
 45→    const first = courses.courses.find((course) => course.eligible > 0) ?? courses.courses[0];
 46→    if (first) setCourseId(first.id);
 47→  }, [courses, courseId]);
 48→
 49→  useEffect(() => {
 50→    closeRef.current?.focus();
 51→    const handler = (event: KeyboardEvent) => {
 52→      if (event.key === "Escape") onClose();
 53→    };
 54→    document.addEventListener("keydown", handler);
 55→    return () => document.removeEventListener("keydown", handler);
 56→  }, [onClose]);
 57→
 58→  const selectedCourse =
 59→    courses.kind === "ready" ? courses.courses.find((course) => course.id === courseId) : undefined;
 60→  const pending = result.kind === "pending";
 61→
 62→  function selectCourse(nextId: string) {
 63→    // A new course is a new logical operation: new idempotency key.
 64→    keyRef.current = crypto.randomUUID();
 65→    setCourseId(nextId);
 66→    setResult({ kind: "idle" });
 67→  }
 68→
 69→  function newOperation() {
 70→    keyRef.current = crypto.randomUUID();
 71→    setResult({ kind: "idle" });
 72→  }
 73→
 74→  async function submit() {
 75→    if (!courseId || pending) return;
 76→    setResult({ kind: "pending" });
 77→    try {
 78→      const { data, replayed } = await bulkIssue(actor, courseId, keyRef.current);
 79→      setResult({ kind: "done", data, replayed });
 80→      onCompleted(`Issued ${data.summary.issued} of ${data.summary.total} learner(s) · ${data.courseTitle}`);
 81→    } catch (error) {
 82→      const keyReuse = error instanceof ApiError && error.code === "idempotency_key_reuse";
 83→      setResult({ kind: "error", message: messageOf(error), retryable: !keyReuse });
 84→    }
 85→  }
 86→
 87→  return (
 88→    <div
 89→      className="modal-overlay"
 90→      onMouseDown={(event) => {
 91→        if (event.target === event.currentTarget && !pending) onClose();
 92→      }}
 93→    >
 94→      <div className="modal" role="dialog" aria-modal="true" aria-labelledby="bulk-title">
 95→        <header className="modal-header">
 96→          <div>
 97→            <p className="eyebrow">Bulk issue</p>
 98→            <h2 id="bulk-title">Issue certificates</h2>
 99→          </div>
100→          <button ref={closeRef} type="button" className="icon-button" onClick={onClose} aria-label="Close" disabled={pending}>
101→            ×
102→          </button>
103→        </header>
104→
105→        <div className="modal-body">
106→          {courses.kind === "loading" ? <p className="muted">Loading courses…</p> : null}
107→
108→          {courses.kind === "error" ? (
109→            <>
110→              <Banner kind="error">{courses.message}</Banner>
111→              <button type="button" className="btn btn-secondary" onClick={() => setReload((value) => value + 1)}>
112→                Try again
113→              </button>
114→            </>
115→          ) : null}
116→
117→          {courses.kind === "ready" && result.kind !== "done" ? (
118→            <form
119→              className="bulk-form"
120→              onSubmit={(event) => {
121→                event.preventDefault();
122→                void submit();
123→              }}
124→            >
125→              <label className="field">
126→                <span>Course</span>
127→                <select value={courseId} onChange={(event) => selectCourse(event.target.value)} disabled={pending}>
128→                  {courses.courses.map((course) => (
129→                    <option key={course.id} value={course.id}>
130→                      {course.title} — {course.eligible} eligible
131→                    </option>
132→                  ))}
133→                </select>
134→              </label>
135→
136→              {selectedCourse ? (
137→                <div className="stats-grid">
138→                  <div className="stat">
139→                    <span className="stat-value">{selectedCourse.eligible}</span>
140→                    <span className="stat-label">Eligible now</span>
141→                  </div>
142→                  <div className="stat">
143→                    <span className="stat-value">{selectedCourse.certified}</span>
144→                    <span className="stat-label">Already certified</span>
145→                  </div>
146→                  <div className="stat">
147→                    <span className="stat-value">{selectedCourse.incomplete}</span>
148→                    <span className="stat-label">Incomplete</span>
149→                  </div>
150→                </div>
151→              ) : null}
152→
153→              <p className="hint">
154→                Incomplete learners and learners who already hold a certificate are skipped — the response
155→                reports every outcome. Reusing an <code>Idempotency-Key</code> replays the stored result
156→                instead of issuing again.
157→              </p>
158→
159→              {result.kind === "error" ? <Banner kind="error">{result.message}</Banner> : null}
160→
161→              <div className="modal-actions">
162→                <button type="button" className="btn btn-ghost" onClick={onClose} disabled={pending}>
163→                  Cancel
164→                </button>
165→                <button
166→                  type="submit"
167→                  className="btn btn-primary"
168→                  disabled={pending || !courseId || (selectedCourse?.eligible ?? 0) === 0}
169→                >
170→                  {pending
171→                    ? "Issuing…"
172→                    : selectedCourse
173→                      ? `Issue to ${selectedCourse.eligible} learner${selectedCourse.eligible === 1 ? "" : "s"}`
174→                      : "Select a course"}
175→                </button>
176→              </div>
177→            </form>
178→          ) : null}
179→
180→          {result.kind === "done" ? (
181→            <div className="bulk-result">
182→              <div className="summary-chips">
183→                <span className="chip chip-issued">Issued {result.data.summary.issued}</span>
184→                <span className="chip chip-skipped">Skipped {result.data.summary.skipped}</span>
185→                <span className="chip chip-failed">Failed {result.data.summary.failed}</span>
186→                <span className="chip chip-total">Total {result.data.summary.total}</span>
187→              </div>
188→              <p className="muted mono">
189→                operation {result.data.operationId} · {result.data.courseTitle}
190→              </p>
191→              {result.replayed ? (
192→                <Banner kind="info">
193→                  Replayed the stored outcome for this Idempotency-Key — no certificate was issued twice.
194→                </Banner>
195→              ) : null}
196→
197→              <div className="outcome-table-wrap">
198→                <table className="outcome-table">
199→                  <thead>
200→                    <tr>
201→                      <th scope="col">Learner</th>
202→                      <th scope="col">Outcome</th>
203→                      <th scope="col">Detail</th>
204→                    </tr>
205→                  </thead>
206→                  <tbody>
207→                    {result.data.outcomes.map((outcome) => (
208→                      <tr key={outcome.learnerId}>
209→                        <td>{outcome.learnerName}</td>
210→                        <td>
211→                          <span className={`badge badge-outcome-${outcome.status}`}>{outcome.status}</span>
212→                        </td>
213→                        <td className="muted">
214→                          {outcome.status === "issued"
215→                            ? outcome.serial
216→                            : (outcome.message ?? outcome.reason ?? "—")}
217→                        </td>
218→                      </tr>
219→                    ))}
220→                  </tbody>
221→                </table>
222→              </div>
223→
224→              <div className="modal-actions">
225→                <button type="button" className="btn btn-secondary" onClick={newOperation}>
226→                  New operation
227→                </button>
228→                <button type="button" className="btn btn-primary" onClick={onClose}>
229→                  Done
230→                </button>
231→              </div>
232→            </div>
233→          ) : null}
234→        </div>
235→      </div>
236→    </div>
237→  );
238→}

